def build_agent(sandbox):
    # Main beam at y=2.0m for buoyancy
    beam = sandbox.add_beam(x=4.0, y=2.0, width=1.0, height=0.5, density=50.0)
    # Add 8 paddles spaced along the beam
    paddles = []
    for i in range(8):
        x = 4.0 + 0.1 * i  # Spread out the paddles along the beam
        paddle = sandbox.add_beam(x, 2.0, 0.1, 0.1, density=100.0)
        # Connect with rigid joints to maintain structural integrity
        sandbox.add_joint(beam, paddle, (x, 2.0), type='rigid')
        paddles.append(paddle)
    return beam

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        # Stop when reaching target
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    # Apply 1 N forward force to each paddle
    for body in sandbox.bodies:
        if body is not agent_body:
            # Apply force in x-direction (forward)
            sandbox.apply_force(body, 1.0, 0.0, step_count=step_count)
